{
  "units": [
    {
      "quote": "The term “applicant” is used hereinafter for the individual whose citizenship and identity is being adjudicated, including for form DS-2060.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "The term \"applicant\" is defined as and used to refer to the individual whose citizenship and identity is being adjudicated, including in the context of form DS-2060."
    },
    {
      "quote": "For purposes of this chapter, minor applicants are defined as un-emancipated applicants under the age of 18.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "For the purposes of this chapter, minor applicants are defined as un-emancipated individuals under the age of 18."
    },
    {
      "quote": "8 FAM 403.1-4 Material Discrepancies (Major name changes)  (CT:CITZ-141; 03-10-2026)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "This text provides section numbering, title, and administrative update metadata without substantive legal or procedural directives."
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "A material discrepancy is defined as any name change that does not qualify as immaterial under 8 FAM 403.1-5."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The applicant is required to explain any material discrepancies existing between the name stated on the passport application and the name shown in the evidence of U.S. citizenship/non-citizen U.S. nationality and identity evidence."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Subject to the exception for married names in 8 FAM 403.1-4(C), any material discrepancy between the name on the application, the evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submitting at least one of the qualifying documents specified in this section."
    },
    {
      "quote": "(a) Name change orders; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under acceptable documentation per 22 CFR 51.25, court orders for a name change constitute an acceptable document type to evidence a material name change."
    },
    {
      "quote": "(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under acceptable documentation per 22 CFR 51.25, court-ordered divorce decrees constitute an acceptable document type to evidence a material name change."
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, certificates of naturalization serve as an acceptable document type to prove a material name change."
    },
    {
      "quote": "(3) Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, marriage certificates constitute an acceptable means of documenting a material name change."
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation showing that a name changed by operation of state law is an acceptable means to document a material name change."
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation evidencing customary usage of the name constitutes an acceptable means of documenting a material name change."
    },
    {
      "quote": "Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Adjudicators are obligated to examine submitted evidence of material name changes for signs of alteration or counterfeiting in accordance with 8 FAM 201.1."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "Following a material name change, an applicant is prohibited from continuing to use their previous name, unless the name change documentation contains specific authorization permitting continued use of that previous name."
    },
    {
      "quote": "Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [
        "The applicant's name is an integral part of her/his identity."
      ],
      "kind": "permission",
      "meaning": "Because an applicant's name is an integral component of identity, adjudicators have the authority under 22 CFR 51.23(c) and Department guidance to require evidence of identity to establish which name best identifies the applicant."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [
        "under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "When an applicant applying on form DS-11 underwent a material name change more than one year earlier without updating their ID to reflect the new name, the adjudicator must suspend the application and request acceptable ID issued in the new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ],
      "kind": "permission",
      "meaning": "In the event that an applicant with an outdated ID from a material name change over a year old faces urgent or emergency travel and there is insufficient time to request and obtain acceptable ID, a limited-validity passport may be issued in the requested name."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "As a qualified general rule, applicants will require their name change documentation in order to update the name displayed on their ID."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL); and",
      "scope_quotes": [
        "The applicant generally will need the name change documentation to change the name on her/his ID."
      ],
      "kind": "requirement",
      "meaning": "Before returning the name change documentation to the applicant alongside an information request letter (IRL), the adjudicator must fully notate the documentation, including entering the notation that it was 'seen and returned'."
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Applicants who experienced a material name change within one year prior to applying on form DS-11 are exempt from having to submit identification in their new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "If an applicant whose material name change occurred within one year of applying on form DS-11 has not yet updated their ID, they are mandatory required to submit their name change documentation."
    },
    {
      "quote": "The court order or decree must be final:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Any court order or decree submitted must be final to be acceptable."
    }
  ]
}
